<script setup>
import { ref, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MInput from '../../../components/mds/MInput.vue'; import MTag from '../../../components/mds/MTag.vue';
const props = defineProps({ rows: { type: Array, default: () => [] }, total: Number, page: Number, pageSize: Number, search: String, loading: Boolean, canCreate: Boolean }); const emit = defineEmits(['search','page','create']); const query = ref(props.search || ''); watch(() => props.search, (v) => { query.value = v || ''; });
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[1200px] space-y-4"><header class="rounded-lg bg-[var(--mds-bg)] px-5 py-4 shadow-[var(--mds-shadow-card)]"><div class="flex items-start justify-between gap-3"><div><h1 class="text-[20px] font-semibold">Sự kiện</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Danh sách sự kiện từ projection R087.</p></div><MButton v-if="canCreate" variant="primary" @click="emit('create')">Thêm sự kiện</MButton></div><form class="mt-4 flex max-w-[560px] gap-2" @submit.prevent="emit('search', query.trim())"><MInput v-model="query" placeholder="Tìm sự kiện hoặc đơn vị tổ chức…" /><MButton variant="primary" :loading="loading" @click="emit('search', query.trim())">Tìm</MButton></form></header><section class="overflow-hidden rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><div class="border-b border-[var(--mds-border-light)] px-5 py-3 text-[13px] text-[var(--mds-text-secondary)]">{{ total || 0 }} sự kiện</div><div v-if="rows.length" class="overflow-x-auto"><table class="w-full min-w-[700px] text-left"><thead class="bg-[var(--mds-bg-page)] text-[12px] text-[var(--mds-text-secondary)]"><tr><th class="px-5 py-3">Sự kiện</th><th class="px-3 py-3">Thời gian</th><th class="px-3 py-3">Đơn vị tổ chức</th><th class="px-5 py-3">Trạng thái</th></tr></thead><tbody class="divide-y divide-[var(--mds-border-light)]"><tr v-for="row in rows" :key="row.id"><td class="px-5 py-3"><strong class="block text-[13px]">{{ row.name }}</strong><span class="text-[12px] text-[var(--mds-text-secondary)]">{{ row.location || 'Chưa cập nhật địa điểm' }}</span></td><td class="px-3 py-3 text-[13px]">{{ row.start_time || '—' }}</td><td class="px-3 py-3 text-[13px]">{{ row.organizer || row.org_name || '—' }}</td><td class="px-5 py-3"><MTag color="neutral">{{ row.status || 'Chưa cập nhật' }}</MTag></td></tr></tbody></table></div><MEmptyState v-else-if="!loading" title="Chưa có sự kiện" description="Sự kiện được phép xem sẽ xuất hiện tại đây." /><div v-else class="p-8 text-center text-[13px] text-[var(--mds-text-secondary)]">Đang tải sự kiện…</div></section><footer class="flex justify-end gap-2"><MButton variant="neutral" :disabled="loading || page <= 1" @click="emit('page', page - 1)">Trang trước</MButton><MButton variant="neutral" :disabled="loading || page * pageSize >= total" @click="emit('page', page + 1)">Trang sau</MButton></footer></div></section></template>
